#include<bits/stdc++.h>
#define int long long
using namespace std;
struct node{
	int x,y;
};
int n,t,ans,sum;
vector<int>vans;
vector<node>v[5555];
void dfs(int p,int d,int sum,vector<int>&o){
	if(p==n){
		if(d<t){
			if(ans<sum){
				ans=sum;
				vans=o;
			}
		}
		return ;
	}else{
		for(int i=0;i<v[p].size();i++){
			o.push_back(v[p][i].x);
			dfs(v[p][i].x,d+v[p][i].y,sum+1,o);
			o.pop_back();
		}
	}
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int m;
	cin>>n>>m>>t;
	for(int i=1;i<=m;i++){
		int x,y,z;
		cin>>x>>y>>z;
		v[x].push_back({y,z});
	}
	vector<int>o;
	o.push_back(1);
	dfs(1,0,1,o);
	cout<<ans<<endl;;
	for(int i=0;i<vans.size();i++){
		cout<<vans[i]<<" ";
	}
    return 0;
}
